import{_ as c,V as i,W as l,X as u,Z as n,$ as a,a0 as t,a1 as s,Y as r,F as p}from"./framework-b1bd8911.js";const d={},k=n("h1",{id:"java-phantomjs-实现-html-输出图片",tabindex:"-1"},[n("a",{class:"header-anchor",href:"#java-phantomjs-实现-html-输出图片","aria-hidden":"true"},"#"),s(" Java & PhantomJs 实现 html 输出图片")],-1),m=n("blockquote",null,[n("p",null,"借助 phantomJs 来实现将 html 网页输出为图片")],-1),v=n("p",null,[s("在 quick-media 的体系里，html 转图片其实有两套方案：一套是 markdown-plugin 里基于 "),n("code",null,"xhtmlrenderer"),s(" 的纯 Java 渲染，另一套就是本文要说的，把 html 丢给无头浏览器 phantomjs 渲染，然后截屏输出图片。")],-1),h=r(`<h2 id="_1-为什么需要-phantomjs" tabindex="-1"><a class="header-anchor" href="#_1-为什么需要-phantomjs" aria-hidden="true">#</a> 1. 为什么需要 phantomjs</h2><p>先聊一下问题背景：我们希望实现的效果是「给一个网页地址，输出这个网页渲染之后的截图」。</p><p>纯 Java 的方案（<code>xhtmlrenderer</code>，也就是 markdown-plugin 中 <code>Html2ImageWrapper</code> 的实现思路）是自己解析 html、自己排版、自己绘制，好处是不依赖任何外部程序，坏处也很明显：</p><ul><li>它本质上是一个简化的排版引擎，css 支持有限，复杂的样式（如 flex、部分 js 动态渲染的内容）基本玩不转</li><li>html 里的 js 不会执行，页面上靠 ajax/js 拉取的内容拿不到</li><li>适合场景是「我们自己生成的、结构可控的 html」（比如 markdown 转出来的），而不是任意的线上网页</li></ul><p>而 phantomjs 是一个基于 WebKit 内核的无界面浏览器，它和真正的浏览器一样加载页面、执行 js、应用 css 样式，然后我们可以让它对当前页面截屏。也就是说，<strong>凡是浏览器能正常显示的页面，phantomjs 都能把它截成图</strong>，这就把渲染的复杂度从 Java 侧转嫁给了浏览器内核。</p><p>两个方案的简单对比：</p><table><thead><tr><th style="text-align:center;">对比项</th><th style="text-align:center;">xhtmlrenderer（markdown-plugin）</th><th style="text-align:center;">phantomjs（本文）</th></tr></thead><tbody><tr><td style="text-align:center;">依赖</td><td style="text-align:center;">纯 Java，无外部依赖</td><td style="text-align:center;">需要本机安装 phantomjs</td></tr><tr><td style="text-align:center;">js 支持</td><td style="text-align:center;">不执行 js</td><td style="text-align:center;">完整执行 js</td></tr><tr><td style="text-align:center;">css 支持</td><td style="text-align:center;">简单样式</td><td style="text-align:center;">WebKit 内核支持</td></tr><tr><td style="text-align:center;">使用场景</td><td style="text-align:center;">结构可控的 html（如 markdown 生成的）</td><td style="text-align:center;">任意线上 url</td></tr><tr><td style="text-align:center;">输出控制</td><td style="text-align:center;">宽高自适应、输出格式等都可配置</td><td style="text-align:center;">截图结果即浏览器显示效果，参数较少</td></tr></tbody></table><p>所以如果你的需求是「markdown 转 html 再转图片」，用 markdown-plugin 那套就够了；如果是「把一个线上网页存成图片」，phantomjs 方案更合适。</p><h2 id="_2-前提准备-安装-phantomjs" tabindex="-1"><a class="header-anchor" href="#_2-前提准备-安装-phantomjs" aria-hidden="true">#</a> 2. 前提准备：安装 phantomjs</h2><p>phantom-plugin 本身只是「调用方」，真正干活的是本机的 phantomjs 程序，所以第一步得把它装好。这里以 2.1.1 版本为例。</p><h3 id="_2-1-mac-系统" tabindex="-1"><a class="header-anchor" href="#_2-1-mac-系统" aria-hidden="true">#</a> 2.1 mac 系统</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 下载</span>
<span class="token function">wget</span> https://bitbucket.org/ariya/phantomjs/downloads/phantomjs-2.1.1-macosx.zip

<span class="token comment"># 解压后，将可执行文件放到 PATH 目录下</span>
<span class="token function">sudo</span> <span class="token function">cp</span> phantomjs-2.1.1-macosx/bin/phantomjs /usr/local/bin

<span class="token comment"># 验证是否 ok</span>
phantomjs <span class="token parameter variable">--version</span>
<span class="token comment"># 输出版本号，则表示 ok</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-2-linux-系统" tabindex="-1"><a class="header-anchor" href="#_2-2-linux-系统" aria-hidden="true">#</a> 2.2 linux 系统</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 下载</span>
<span class="token function">wget</span> https://bitbucket.org/ariya/phantomjs/downloads/phantomjs-2.1.1-linux-x86_64.tar.bz2

<span class="token comment"># 解压</span>
<span class="token function">sudo</span> <span class="token function">su</span>
<span class="token function">tar</span> <span class="token parameter variable">-jxvf</span> phantomjs-2.1.1-linux-x86_64.tar.bz2

<span class="token comment"># 如果解压报错，则先安装下面的</span>
<span class="token comment"># yum -y install bzip2</span>

<span class="token comment"># 简单点，移动到 bin 目录下</span>
<span class="token function">cp</span> phantomjs-2.1.1-linux-x86_64/bin/phantomjs /usr/local/bin

<span class="token comment"># 验证</span>
phantomjs <span class="token parameter variable">--version</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-3-windows-系统" tabindex="-1"><a class="header-anchor" href="#_2-3-windows-系统" aria-hidden="true">#</a> 2.3 windows 系统</h3><p>老文档里写的是「就不要玩了，没啥意思」😂，不过 Windows 下其实也能跑：下载 <code>phantomjs-2.1.1-windows.zip</code> 解压，记住 <code>bin\\phantomjs.exe</code> 的绝对路径（比如 <code>D:/soft/phantomjs/bin/phantomjs.exe</code>），后面通过 JVM 系统属性告诉 Java 进程即可（见下文 3.2 节），不强求配置环境变量。</p><p>如果希望通过 <code>phantomjs --version</code> 直接验证，则可以把 <code>bin</code> 目录加到系统的 <code>Path</code> 环境变量里。</p><h3 id="_2-4-linux-下的中文字体" tabindex="-1"><a class="header-anchor" href="#_2-4-linux-下的中文字体" aria-hidden="true">#</a> 2.4 linux 下的中文字体</h3><p>如果是在 linux 服务器上用，且页面包含中文，请确保系统安装了中文字体，否则截图里的中文会变成一个个方框：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># centos</span>
yum <span class="token function">install</span> <span class="token parameter variable">-y</span> fontconfig
yum <span class="token function">install</span> <span class="token parameter variable">-y</span> wqy-microhei-fonts wqy-zenhei-fonts
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这是 phantomjs 系方案（包括后面会聊的 selenium 无头浏览器）的经典坑，渲染乱码十有八九是机器上没有字体。</p><h2 id="_3-依赖引入" tabindex="-1"><a class="header-anchor" href="#_3-依赖引入" aria-hidden="true">#</a> 3. 依赖引入</h2><blockquote><p>项目已发布到 maven 中央仓库，直接依赖即可</p></blockquote><h3 id="_3-1-maven" tabindex="-1"><a class="header-anchor" href="#_3-1-maven" aria-hidden="true">#</a> 3.1 maven</h3><div class="language-xml line-numbers-mode" data-ext="xml"><pre class="language-xml"><code><span class="token comment">&lt;!-- https://mvnrepository.com/artifact/com.github.liuyueyi.media/phantom-plugin --&gt;</span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>dependency</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>groupId</span><span class="token punctuation">&gt;</span></span>com.github.liuyueyi.media<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>groupId</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>artifactId</span><span class="token punctuation">&gt;</span></span>phantom-plugin<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>artifactId</span><span class="token punctuation">&gt;</span></span>
    <span class="token comment">&lt;!-- 以中央仓库最新版本为准 --&gt;</span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>version</span><span class="token punctuation">&gt;</span></span>3.1.0<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>version</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>dependency</span><span class="token punctuation">&gt;</span></span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>内部依赖了 <code>selenium-java</code>（selenium 官方提供的 phantomjs driver）与 <code>ghostdriver</code>（phantomjs 的 webdriver 实现，来自 jitpack 仓库），如果你选择自己拉源码编译，需要留意 pom 里有 jitpack 的仓库配置。</p><h3 id="_3-2-指定-phantomjs-的可执行路径" tabindex="-1"><a class="header-anchor" href="#_3-2-指定-phantomjs-的可执行路径" aria-hidden="true">#</a> 3.2 指定 phantomjs 的可执行路径</h3><p>插件是如何找到 phantomjs 的？看一眼源码：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token keyword">private</span> <span class="token keyword">static</span> <span class="token class-name">String</span> <span class="token function">getPhantomJsPath</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token class-name">String</span> path <span class="token operator">=</span> <span class="token class-name">System</span><span class="token punctuation">.</span><span class="token function">getProperty</span><span class="token punctuation">(</span><span class="token string">&quot;phantomjs.binary.path&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>path <span class="token operator">==</span> <span class="token keyword">null</span> <span class="token operator">||</span> <span class="token string">&quot;&quot;</span><span class="token punctuation">.</span><span class="token function">endsWith</span><span class="token punctuation">(</span>path<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token string">&quot;/usr/local/bin/phantomjs&quot;</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> path<span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>逻辑非常直白：</p><ul><li>优先读取 JVM 系统属性 <code>phantomjs.binary.path</code></li><li>没有配置时，兜底使用 <code>/usr/local/bin/phantomjs</code> —— 这也是为什么上面推荐把可执行文件拷到 <code>/usr/local/bin</code> 下</li></ul><p>所以两种姿势二选一：</p><ol><li>把 phantomjs 放到 <code>/usr/local/bin</code> 下（mac/linux 省事）</li><li>启动时带上系统属性：</li></ol><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 命令行方式</span>
<span class="token function">java</span> <span class="token parameter variable">-Dphantomjs.binary.path</span><span class="token operator">=</span>/Users/yihui/soft/phantomjs/bin/phantomjs <span class="token parameter variable">-jar</span> xxx.jar

<span class="token comment"># windows 示例</span>
<span class="token function">java</span> <span class="token parameter variable">-Dphantomjs.binary.path</span><span class="token operator">=</span>D:/soft/phantomjs/bin/phantomjs.exe <span class="token parameter variable">-jar</span> xxx.jar
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>代码内也可以在创建 driver 之前设置一次（注意插件是类加载时初始化的，最好在应用启动最前面做）：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token class-name">System</span><span class="token punctuation">.</span><span class="token function">setProperty</span><span class="token punctuation">(</span><span class="token string">&quot;phantomjs.binary.path&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;D:/soft/phantomjs/bin/phantomjs.exe&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h2 id="_4-使用姿势" tabindex="-1"><a class="header-anchor" href="#_4-使用姿势" aria-hidden="true">#</a> 4. 使用姿势</h2><p>这个插件对外暴露的 API 非常克制，整个插件就一个工具类 <code>Html2ImageByJsWrapper</code>，就一个静态方法：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token doc-comment comment">/**
 * 渲染 url 对应的网页，并输出截图
 */</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">BufferedImage</span> <span class="token function">renderHtml2Image</span><span class="token punctuation">(</span><span class="token class-name">String</span> url<span class="token punctuation">)</span> <span class="token keyword">throws</span> <span class="token class-name">IOException</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>以项目自带的测试 case 为例（<code>Html2ImgTest#testRender</code>）：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token annotation punctuation">@Test</span>
<span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">testRender</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token class-name">BufferedImage</span> img <span class="token operator">=</span> <span class="token keyword">null</span><span class="token punctuation">;</span>
    <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">int</span> i <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> i <span class="token operator">&lt;</span> <span class="token number">20</span><span class="token punctuation">;</span> <span class="token operator">++</span>i<span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token class-name">String</span> url <span class="token operator">=</span> <span class="token string">&quot;https://my.oschina.net/u/566591/blog/1580020&quot;</span><span class="token punctuation">;</span>
        <span class="token keyword">long</span> start <span class="token operator">=</span> <span class="token class-name">System</span><span class="token punctuation">.</span><span class="token function">currentTimeMillis</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        img <span class="token operator">=</span> <span class="token class-name">Html2ImageByJsWrapper</span><span class="token punctuation">.</span><span class="token function">renderHtml2Image</span><span class="token punctuation">(</span>url<span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token keyword">long</span> end <span class="token operator">=</span> <span class="token class-name">System</span><span class="token punctuation">.</span><span class="token function">currentTimeMillis</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span><span class="token string">&quot;cost:  &quot;</span> <span class="token operator">+</span> <span class="token punctuation">(</span>end <span class="token operator">-</span> start<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>传一个线上 url 进去，返回的就是渲染之后的 <code>BufferedImage</code>，拿到之后该怎么用就怎么用，比如直接落盘：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token class-name">BufferedImage</span> img <span class="token operator">=</span> <span class="token class-name">Html2ImageByJsWrapper</span><span class="token punctuation">.</span><span class="token function">renderHtml2Image</span><span class="token punctuation">(</span><span class="token string">&quot;https://blog.hhui.top&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token class-name">ImageIO</span><span class="token punctuation">.</span><span class="token function">write</span><span class="token punctuation">(</span>img<span class="token punctuation">,</span> <span class="token string">&quot;png&quot;</span><span class="token punctuation">,</span> <span class="token keyword">new</span> <span class="token class-name">File</span><span class="token punctuation">(</span><span class="token string">&quot;/tmp/render.png&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>如果希望在前端网页中直接展示，可以配合 base-plugin 里的工具类，把图片转成 base64 的 data-uri 格式：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token keyword">import</span> <span class="token import"><span class="token namespace">com<span class="token punctuation">.</span>github<span class="token punctuation">.</span>hui<span class="token punctuation">.</span>quick<span class="token punctuation">.</span>plugin<span class="token punctuation">.</span>base<span class="token punctuation">.</span></span><span class="token class-name">Base64Util</span></span><span class="token punctuation">;</span>
<span class="token keyword">import</span> <span class="token import"><span class="token namespace">com<span class="token punctuation">.</span>github<span class="token punctuation">.</span>hui<span class="token punctuation">.</span>quick<span class="token punctuation">.</span>plugin<span class="token punctuation">.</span>base<span class="token punctuation">.</span></span><span class="token class-name">DomUtil</span></span><span class="token punctuation">;</span>
<span class="token keyword">import</span> <span class="token import"><span class="token namespace">com<span class="token punctuation">.</span>github<span class="token punctuation">.</span>hui<span class="token punctuation">.</span>quick<span class="token punctuation">.</span>plugin<span class="token punctuation">.</span>base<span class="token punctuation">.</span>constants<span class="token punctuation">.</span></span><span class="token class-name">MediaType</span></span><span class="token punctuation">;</span>

<span class="token comment">// 输出可以直接塞进 &lt;img src=&quot;...&quot;&gt; 的 data-uri 字符串</span>
<span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span><span class="token class-name">DomUtil</span><span class="token punctuation">.</span><span class="token function">toDomSrc</span><span class="token punctuation">(</span><span class="token class-name">Base64Util</span><span class="token punctuation">.</span><span class="token function">encode</span><span class="token punctuation">(</span>img<span class="token punctuation">,</span> <span class="token string">&quot;png&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token class-name">MediaType<span class="token punctuation">.</span>ImagePng</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_5-内部是怎么干的" tabindex="-1"><a class="header-anchor" href="#_5-内部是怎么干的" aria-hidden="true">#</a> 5. 内部是怎么干的</h2><p>虽然它只是个薄薄的封装，但把核心源码贴出来过一遍，有助于理解后面的一些坑：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">Html2ImageByJsWrapper</span> <span class="token punctuation">{</span>

    <span class="token keyword">private</span> <span class="token keyword">static</span> <span class="token class-name">PhantomJSDriver</span> webDriver<span class="token punctuation">;</span>

    <span class="token keyword">static</span> <span class="token punctuation">{</span>
        <span class="token keyword">try</span> <span class="token punctuation">{</span>
            webDriver <span class="token operator">=</span> <span class="token function">getPhantomJs</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span> <span class="token keyword">catch</span> <span class="token punctuation">(</span><span class="token class-name">Exception</span> e<span class="token punctuation">)</span> <span class="token punctuation">{</span>
            e<span class="token punctuation">.</span><span class="token function">printStackTrace</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">private</span> <span class="token keyword">static</span> <span class="token class-name">PhantomJSDriver</span> <span class="token function">getPhantomJs</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">//设置必要参数</span>
        <span class="token class-name">DesiredCapabilities</span> dcaps <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">DesiredCapabilities</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token comment">//ssl证书支持</span>
        dcaps<span class="token punctuation">.</span><span class="token function">setCapability</span><span class="token punctuation">(</span><span class="token string">&quot;acceptSslCerts&quot;</span><span class="token punctuation">,</span> <span class="token boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token comment">//截屏支持</span>
        dcaps<span class="token punctuation">.</span><span class="token function">setCapability</span><span class="token punctuation">(</span><span class="token string">&quot;takesScreenshot&quot;</span><span class="token punctuation">,</span> <span class="token boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token comment">//css搜索支持</span>
        dcaps<span class="token punctuation">.</span><span class="token function">setCapability</span><span class="token punctuation">(</span><span class="token string">&quot;cssSelectorsEnabled&quot;</span><span class="token punctuation">,</span> <span class="token boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token comment">//js支持</span>
        dcaps<span class="token punctuation">.</span><span class="token function">setJavascriptEnabled</span><span class="token punctuation">(</span><span class="token boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token comment">//驱动支持（第二参数表明的是你的phantomjs引擎所在的路径，which/whereis phantomjs可以查看）</span>
        dcaps<span class="token punctuation">.</span><span class="token function">setCapability</span><span class="token punctuation">(</span><span class="token class-name">PhantomJSDriverService</span><span class="token punctuation">.</span><span class="token constant">PHANTOMJS_EXECUTABLE_PATH_PROPERTY</span><span class="token punctuation">,</span> <span class="token function">getPhantomJsPath</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token comment">//创建无界面浏览器对象</span>
        <span class="token keyword">return</span> <span class="token keyword">new</span> <span class="token class-name">PhantomJSDriver</span><span class="token punctuation">(</span>dcaps<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">BufferedImage</span> <span class="token function">renderHtml2Image</span><span class="token punctuation">(</span><span class="token class-name">String</span> url<span class="token punctuation">)</span> <span class="token keyword">throws</span> <span class="token class-name">IOException</span> <span class="token punctuation">{</span>
        <span class="token keyword">if</span> <span class="token punctuation">(</span>webDriver <span class="token operator">!=</span> <span class="token keyword">null</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            webDriver<span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span>url<span class="token punctuation">)</span><span class="token punctuation">;</span>
            <span class="token class-name">File</span> file <span class="token operator">=</span> webDriver<span class="token punctuation">.</span><span class="token function">getScreenshotAs</span><span class="token punctuation">(</span><span class="token class-name">OutputType</span><span class="token punctuation">.</span><span class="token constant">FILE</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
            <span class="token keyword">return</span> <span class="token class-name">ImageIO</span><span class="token punctuation">.</span><span class="token function">read</span><span class="token punctuation">(</span>file<span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token punctuation">{</span>
            <span class="token keyword">return</span> <span class="token keyword">null</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>几处值得注意的点：</p><ul><li><strong>静态块初始化</strong>：<code>PhantomJSDriver</code> 在类加载时就创建好了，phantomjs 进程随之启动，后续所有的渲染都复用这一个浏览器实例，避免每次截图都拉起进程的开销（测试 case 里循环 20 次渲染并计时，就是为了观察复用之后的耗时表现）</li><li><strong>参数说明</strong>：<code>DesiredCapabilities</code> 里开启了 ssl 证书、截屏、css 选择器、js 支持，都是截网页图的必要开关</li><li><strong>渲染流程</strong>：<code>webDriver.get(url)</code> 会等页面加载完成，然后 <code>getScreenshotAs</code> 对当前窗口截屏，得到一个临时文件，再读成 <code>BufferedImage</code> 返回</li><li><strong>phantomjs 路径</strong>：通过 <code>PHANTOMJS_EXECUTABLE_PATH_PROPERTY</code> 这个 capability 传给了 driver，取值规则见上文 3.2</li></ul><h2 id="_6-常见坑" tabindex="-1"><a class="header-anchor" href="#_6-常见坑" aria-hidden="true">#</a> 6. 常见坑</h2><h3 id="_6-1-找不到-phantomjs-可执行文件" tabindex="-1"><a class="header-anchor" href="#_6-1-找不到-phantomjs-可执行文件" aria-hidden="true">#</a> 6.1 找不到 phantomjs 可执行文件</h3><p>报错一般是 phantomjs driver 初始化失败，栈里会有找不到 executable 之类的提示。排查顺序：</p><ol><li>确认机器上真的装了 phantomjs：<code>which phantomjs</code>（win 上是 <code>where phantomjs</code>）</li><li>确认路径和插件期望的对得上：没有配置 <code>phantomjs.binary.path</code> 时，兜底路径是 <code>/usr/local/bin/phantomjs</code>，只适用于 mac/linux</li><li>windows 用户必须显式配置 <code>-Dphantomjs.binary.path=...</code>，且注意路径分隔符用 <code>/</code> 或 <code>\\\\</code></li></ol><h3 id="_6-2-中文乱码-中文变方框" tabindex="-1"><a class="header-anchor" href="#_6-2-中文乱码-中文变方框" aria-hidden="true">#</a> 6.2 中文乱码 / 中文变方框</h3><p>表现是截图里的中文全是「豆腐块」。原因在前面提过：机器上没有中文字体，phantomjs 渲染时找不到字形。装上字体即可（见 2.4 节），linux 服务器上部署时尤其容易踩。</p><p>另外注意插件默认以 UTF-8 读取文件，如果你的 html 文件本身是 GBK 编码，也可能出现乱码，这类情况属于 html 源文件的问题，改文件编码即可。</p><h3 id="_6-3-截图只有一小块-长网页被截断" tabindex="-1"><a class="header-anchor" href="#_6-3-截图只有一小块-长网页被截断" aria-hidden="true">#</a> 6.3 截图只有一小块 / 长网页被截断</h3><p>phantomjs 截屏截的是「当前视口」，默认窗口尺寸比较小（400x300），所以页面超长时会只截到第一屏。</p><p>这是方案本身的限制：<code>Html2ImageByJsWrapper</code> 没有暴露设置视口大小的参数。如果遇到这种场景，可以下载源码自己改造——<code>PhantomJSDriver</code> 实现了标准 WebDriver 接口，在 <code>renderHtml2Image</code> 里调用 <code>webDriver.manage().window().setSize(new Dimension(w, h))</code> 即可放大视口；或者干脆按自己的需求 fork 一份 wrapper（整个类也就七十来行，改造成本很低）。</p><h3 id="_6-4-页面加载超时" tabindex="-1"><a class="header-anchor" href="#_6-4-页面加载超时" aria-hidden="true">#</a> 6.4 页面加载超时</h3><p><code>webDriver.get(url)</code> 是同步阻塞的，页面一直加载不完时，调用就会一直挂着。如果渲染的 url 来自外部输入，建议在外面套一层自己的超时控制（如异步线程 + 超时取消），不要让一次异常的页面加载拖垮整个服务。</p><p>网络不佳时，页面里引用的远程图片、css 加载失败，也会导致截图内容不完整，这一点在弱网环境下要有心理预期。</p><h3 id="_6-5-并发支持有限" tabindex="-1"><a class="header-anchor" href="#_6-5-并发支持有限" aria-hidden="true">#</a> 6.5 并发支持有限</h3><p>插件内部只有一个静态的 <code>webDriver</code> 实例，<code>renderHtml2Image</code> 串行使用它是安全的，但多线程并发调用同一个无头浏览器实例并没有得到保证。如果业务上是高并发场景，稳妥的做法是自己基于 selenium + ghostdriver 搭建一个 phantomjs 实例池（或者每个线程一个实例），不要直接并发怼这个工具类。</p><h3 id="_6-6-时代局限" tabindex="-1"><a class="header-anchor" href="#_6-6-时代局限" aria-hidden="true">#</a> 6.6 时代局限</h3><p>phantomjs 项目官方已经停止维护，其 WebKit 内核相对老旧，对新的 js 语法、新的 css 特性支持有限，遇到新潮的网页可能会渲染异常或直接加载失败。这是选型时需要心里有数的：phantomjs 方案胜在简单、有历史沉淀，但如果要求对新页面有良好的兼容性，可以考虑换成基于 chrome 的 headless 方案，思路完全一致（同样是 selenium 驱动 + 截屏），只是驱动换成了 ChromeDriver。</p><h2 id="_7-小结" tabindex="-1"><a class="header-anchor" href="#_7-小结" aria-hidden="true">#</a> 7. 小结</h2><p>phantom-plugin 提供的是一个非常轻量的封装：<code>Html2ImageByJsWrapper.renderHtml2Image(url)</code> 一行调用，把「网页」变成「图片」。它和 markdown-plugin 的 xhtmlrenderer 方案互补——后者擅长渲染我们自己生成的 html，前者擅长截真实的线上网页。</p><p>使用它的三要素：</p><ol><li>本机装好 phantomjs 2.1.1</li><li>保证 Java 进程能找到可执行文件（环境变量 或 <code>phantomjs.binary.path</code>）</li><li>注意视口大小、字体、超时这几个经典坑</li></ol><p><strong>相关文档：</strong></p>`,72),b=n("strong",null,"项目地址：",-1),g={href:"https://github.com/liuyueyi/quick-media",target:"_blank",rel:"noopener noreferrer"};function j(y,f){const e=p("RouterLink"),o=p("ExternalLinkIcon");return i(),l("div",null,[k,m,v,u(" more "),h,n("ul",null,[n("li",null,[a(e,{to:"/git/quick-media/base/01.%E5%85%AC%E5%85%B1%E5%B7%A5%E5%85%B7%E7%B1%BB%E9%80%9F%E6%9F%A5.html"},{default:t(()=>[s("base-plugin 公共工具类速查")]),_:1})]),n("li",null,[a(e,{to:"/git/quick-media/markdown/"},{default:t(()=>[s("markdown 转图片")]),_:1})])]),n("p",null,[b,s(),n("a",g,[s("https://github.com/liuyueyi/quick-media"),a(o)])])])}const w=c(d,[["render",j],["__file","01.基于PhantomJs实现html输出图片.html.vue"]]);export{w as default};
